   [89]={next_id=90, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我的父母，只是两个技术很好却没什么名气的普通裁缝……我也只不过是个裁缝家的女儿。", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他们庇护了被暗杀的霍亨索伦公爵夫妇，因而遭到灭口，我是那场惨案的幸存者。", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="白蔷薇用手臂遮住自己的脸，如梦呓一般开始了讲述。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="玛莉亚夫人将我带回了霍亨索伦领，并问出了那个问题……", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“你愿意成为我的女儿吗？继承霍亨索伦的姓氏，还有……我们未尽的理想。”", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="理想……那时的我，哪里懂得什么是理想。我只知道，她是唯一能抓住的救命稻草。", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="说到这里，白蔷薇苦笑了一声。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我点了点头，接受了“霍亨索伦”的姓氏，也接受了那份沉重的遗志。", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="后来，我见到了维特伯爵，还有那位唯唯诺诺的皇帝陛下。他们用审视的目光打量我，问我很多很难的问题，都被我一一解答。", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他们说我是“天才”， 是“克罗瓦德的希望”。", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="皇帝陛下膝下无子，而夫人是陛下的亲生姐姐。于是我被送进皇宫，成为了克罗瓦德的皇女。", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你静静地听着她的讲述，夜风吹拂，带来远方的硝烟味。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
